{
  "name": "扫描数据文件读写组件",
  "name_en": "Scan Data File Reader/Writer",
  "manufacturer": "",
  "description": "这是一个非物理的软件组件，用于实验扫描数据文件的打开、读取、写入和关闭。它支持将扫描数据、注释、时间戳、图例、额外过程变量和扫描参数写入文件，也可读取已有扫描文件内容，常用于实验自动化中的数据保存与元数据记录。",
  "description_en": "This is a non-physical software component for opening, reading, writing, flushing, and closing experiment scan data files. It supports writing scan data, comments, timestamps, legends, extra process variables, and scan parameters, and can also read existing scan files. It is commonly used for data logging and metadata capture in laboratory scan workflows.",
  "actions": [
    {
      "action_name": "auto-check_writeable",
      "description": "检查输出扫描文件是否已打开且可写。",
      "description_en": "Check whether the output scan file is open and writable."
    },
    {
      "action_name": "auto-close",
      "description": "关闭扫描数据文件。",
      "description_en": "Close the scan data file."
    },
    {
      "action_name": "auto-flush",
      "description": "将已缓冲的扫描文件内容刷新到磁盘。",
      "description_en": "Flush buffered scan file contents to disk."
    },
    {
      "action_name": "auto-open_for_write",
      "description": "打开扫描数据文件用于写入或追加，并可避免覆盖已有文件名。",
      "description_en": "Open a scan data file for writing or appending, with protection against overwriting an existing filename."
    },
    {
      "action_name": "auto-write",
      "description": "向扫描数据文件写入文本内容。",
      "description_en": "Write text content to the scan data file."
    },
    {
      "action_name": "auto-write_comments",
      "description": "向扫描文件写入注释信息。",
      "description_en": "Write comment information to the scan file."
    },
    {
      "action_name": "auto-write_data",
      "description": "将扫描数据写入文件。",
      "description_en": "Write scan data to the file."
    },
    {
      "action_name": "auto-write_extrapvs",
      "description": "将额外过程变量信息写入扫描文件。",
      "description_en": "Write extra process variable information to the scan file."
    },
    {
      "action_name": "auto-write_legend",
      "description": "向扫描文件写入数据图例或列说明。",
      "description_en": "Write the data legend or column description to the scan file."
    },
    {
      "action_name": "auto-write_timestamp",
      "description": "向扫描文件写入时间戳。",
      "description_en": "Write a timestamp to the scan file."
    },
    {
      "action_name": "auto-get_data",
      "description": "获取已读取的扫描数据内容。",
      "description_en": "Get the scan data content that has been read."
    },
    {
      "action_name": "auto-read",
      "description": "读取扫描数据文件内容。",
      "description_en": "Read the contents of a scan data file."
    },
    {
      "action_name": "auto-write_lines",
      "description": "向扫描文件批量写入多行文本。",
      "description_en": "Write multiple lines of text to the scan file."
    },
    {
      "action_name": "auto-write_scanparams",
      "description": "将扫描参数写入文件。",
      "description_en": "Write scan parameters to the file."
    }
  ],
  "tag_hints": [
    "scan data logging",
    "experiment file I/O",
    "ASCII scan files",
    "scan metadata",
    "timestamp recording",
    "EPICS scan data",
    "process variable logging"
  ]
}

